-- DATOS DE PRUEBA (FICTICIOS) - no corresponden a personas reales
-- 100 estudiantes (33 desertores), 2 facultades, 4 programas, 3 periodos
-- Ejecutar después de schema.sql:  psql -U postgres -d desercion_db -f datos_prueba.sql
BEGIN;

INSERT INTO facultades (nombre) VALUES
    ('Facultad de Ingeniería'),
    ('Facultad de Ciencias Económicas')
ON CONFLICT (nombre) DO NOTHING;

INSERT INTO programas (facultad_id, codigo, nombre)
SELECT f.id, v.codigo, v.nombre FROM (VALUES
    ('ISIS', 'Ingeniería de Sistemas', 'Facultad de Ingeniería'),
    ('ICIV', 'Ingeniería Civil', 'Facultad de Ingeniería'),
    ('ADEM', 'Administración de Empresas', 'Facultad de Ciencias Económicas'),
    ('CPUB', 'Contaduría Pública', 'Facultad de Ciencias Económicas')
) AS v(codigo, nombre, facultad) JOIN facultades f ON f.nombre = v.facultad
ON CONFLICT (codigo) DO NOTHING;

INSERT INTO periodos_academicos (codigo, fecha_inicio, fecha_fin, actual) VALUES
    ('2025-1', DATE '2025-02-03', DATE '2025-06-20', FALSE),
    ('2025-2', DATE '2025-08-04', DATE '2025-12-12', FALSE),
    ('2026-1', DATE '2026-02-02', DATE '2026-06-19', TRUE)
ON CONFLICT (codigo) DO NOTHING;

