INSERT INTO datos_academicos (estudiante_id, periodo_id, semestre_cursado, creditos_inscritos,
    creditos_aprobados, creditos_reprobados, promedio_periodo, promedio_acumulado, asistencia_pct,
    materias_reprobadas, materias_canceladas, materias_repetidas, estado_matricula)
SELECT e.id, p.id, v.semestre_cursado::SMALLINT, v.creditos_inscritos::SMALLINT, v.creditos_aprobados::SMALLINT,
    v.creditos_reprobados::SMALLINT, v.promedio_periodo::NUMERIC, v.promedio_acumulado::NUMERIC,
    v.asistencia_pct::NUMERIC, v.materias_reprobadas::SMALLINT, v.materias_canceladas::SMALLINT,
